let tasks=[],rules=[],revs={},today=null;
const WD=['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
const WDP=['domingos','segundas','terças','quartas','quintas','sextas','sábados'];
const $=id=>document.getElementById(id);
function parse(iso){const p=iso.split('-').map(Number);return new Date(Date.UTC(p[0],p[1]-1,p[2]));}
function iso(d){return d.toISOString().slice(0,10);}
function addDays(s,n){const d=parse(s);d.setUTCDate(d.getUTCDate()+n);return iso(d);}
function wd(s){return parse(s).getUTCDay();}
function fmt(s){return parse(s).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'});}
function msg(id,t,bad){const e=$(id);e.textContent=t;e.className=bad?'err':'ok';}
function allowedDays(blocked){const r=[];for(let i=0;i<14;i++){const d=addDays(today,i);if(!blocked.has(wd(d)))r.push(d);}return r;}
function loadMap(list){const m={};for(const t of list)for(const d of t.dates)m[d]=(m[d]||0)+1;return m;}
function pickBest(cands,load,taken,target){let best=null,bs=null;cands.forEach((d,i)=>{if(taken.has(d))return;const s=[load[d]||0,Math.abs(i-target)];if(!bs||s[0]<bs[0]||(s[0]===bs[0]&&s[1]<bs[1])){best=d;bs=s;}});return best;}
function pickDates(cands,load,k){const n=cands.length,out=new Set();k=Math.min(k,n);for(let j=0;j<k;j++){const target=k===1?0:Math.round(j*(n-1)/(k-1));const win=cands.map((d,i)=>Math.abs(i-target)<=2?d:null);const taken=new Set(out);cands.forEach((d,i)=>{if(Math.abs(i-target)>2)taken.add(d);});let d=pickBest(cands,load,taken,target);if(!d)d=pickBest(cands,load,out,target);out.add(d);load[d]=(load[d]||0)+1;}return Array.from(out).sort();}
async function load(){const r=await tessera.call('data.read',{});tasks=r.data.tasks||[];rules=r.data.rules||[];revs=r.revisions||{};render();}
function render(){
const rl=$('rules');rl.textContent='';
if(!rules.length){const li=document.createElement('li');li.textContent='Nenhum dia bloqueado.';rl.appendChild(li);}
for(const r of rules){const li=document.createElement('li');li.setAttribute('data-hook','rule');const s=document.createElement('span');s.textContent='Nunca às '+WDP[r.weekday];const b=document.createElement('button');b.type='button';b.className='sec';b.setAttribute('data-hook','rule-remove');b.textContent='Remover regra';b.setAttribute('aria-label','Remover regra: nunca às '+WDP[r.weekday]);b.addEventListener('click',()=>removeRule(r));li.append(s,b);rl.appendChild(li);}
const all=[];for(const t of tasks)for(const d of t.dates||[])all.push({name:t.name,date:d});
all.sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:0);
$('empty').hidden=tasks.length>0;
const sl=$('sessions');sl.textContent='';
for(const s of all){const li=document.createElement('li');li.setAttribute('data-hook','session');const tm=document.createElement('time');tm.setAttribute('datetime',s.date);tm.textContent=fmt(s.date)+' à noite';const n=document.createElement('span');n.setAttribute('data-hook','session-task');n.textContent=s.name;li.append(tm,n);sl.appendChild(li);}
const tl=$('tasks');tl.textContent='';
for(const t of tasks){const li=document.createElement('li');const s=document.createElement('span');s.textContent=t.name+' ('+(t.dates||[]).length+' sessões)';const b=document.createElement('button');b.type='button';b.className='sec';b.textContent='Remover assunto';b.setAttribute('aria-label','Remover assunto '+t.name);b.addEventListener('click',()=>removeTask(t));li.append(s,b);tl.appendChild(li);}
}
async function addTask(){
const name=$('tn').value.trim();
if(!name){msg('tmsg','Digite o nome do assunto.',true);return;}
const blocked=new Set(rules.map(r=>r.weekday));
const cands=allowedDays(blocked);
if(!cands.length){msg('tmsg','Todos os dias estão bloqueados. Remova uma regra.',true);return;}
const dates=pickDates(cands,loadMap(tasks),3);
try{await tessera.call('data.patch',{operations:[{op:'add',collection:'tasks',record:{name:name,dates:dates}}]});$('tn').value='';await load();msg('tmsg','Assunto agendado em '+dates.length+' sessões.',false);}catch(e){msg('tmsg','Não foi possível salvar. Tente de novo.',true);}
}
async function addRule(){
const day=Number($('rd').value);
if(rules.some(r=>r.weekday===day)){msg('rmsg','Esse dia já está bloqueado.',true);return;}
const blocked=new Set(rules.map(r=>r.weekday));blocked.add(day);
const cands=allowedDays(blocked);
if(!cands.length){msg('rmsg','Não dá para bloquear todos os dias da semana.',true);return;}
const load={};const base=tasks.map(t=>({dates:(t.dates||[]).filter(d=>!blocked.has(wd(d)))}));
for(const t of base)for(const d of t.dates)load[d]=(load[d]||0)+1;
const ops=[{op:'add',collection:'rules',record:{weekday:day}}];
for(const t of tasks){const keep=(t.dates||[]).filter(d=>!blocked.has(wd(d)));const moved=(t.dates||[]).length-keep.length;if(!moved)continue;const set=new Set(keep);for(let i=0;i<moved;i++){let d=pickBest(cands,load,set,0);if(!d)break;set.add(d);load[d]=(load[d]||0)+1;}
ops.push({op:'replace',collection:'tasks',id:t.id,revisionCount:(revs.tasks||{})[t.id]||1,fields:{dates:Array.from(set).sort()}});}
try{await tessera.call('data.patch',{operations:ops});await load();msg('rmsg','Regra salva. Sessões de '+WD[day]+' foram movidas para outros dias.',false);}catch(e){msg('rmsg','Não foi possível salvar a regra. Tente de novo.',true);}
}
async function removeRule(r){
try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'rules',id:r.id,revisionCount:(revs.rules||{})[r.id]||1}]});await load();msg('rmsg','Regra removida.',false);}catch(e){msg('rmsg','Não foi possível remover a regra.',true);}
}
async function removeTask(t){
try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'tasks',id:t.id,revisionCount:(revs.tasks||{})[t.id]||1}]});await load();msg('tmsg','Assunto removido.',false);}catch(e){msg('tmsg','Não foi possível remover o assunto.',true);}
}
$('ta').addEventListener('click',addTask);
$('tn').addEventListener('keydown',e=>{if(e.key==='Enter')addTask();});
$('ra').addEventListener('click',addRule);
(async()=>{try{const c=await tessera.call('clock.now',{});today=c.date;$('intro').textContent='Estudo à noite, de hoje até a véspera da prova (daqui a duas semanas, '+fmt(addDays(today,14))+').';await load();}catch(e){msg('tmsg','Não foi possível carregar o plano.',true);}})();

