const shown=new Set();
const WD=['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
const WDP=['domingos','segundas','terças','quartas','quintas','sextas','sábados'];
const $=id=>document.getElementById(id);
function parse(iso){const p=iso.split('-').map(Number);return new Date(Date.UTC(p[0],p[1]-1,p[2]));}
function iso(d){return d.toISOString().slice(0,10);}
function addDays(s,n){const d=parse(s);d.setUTCDate(d.getUTCDate()+n);return iso(d);}
function wd(s){return parse(s).getUTCDay();}
function fmt(s){return parse(s).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'});}
function msg(id,t,bad){const e=$(id);e.textContent=t;e.className=bad?'err':'ok';}
function allowedDays(blocked){const r=[];for(let i=0;i<14;i++){const d=addDays(today,i);if(!blocked.has(wd(d)))r.push(d);}return r;}
function loadMap(list){const m={};for(const t of list)for(const d of t.dates||[])m[d]=(m[d]||0)+1;return m;}
function pickBest(cands,ld,taken,target){let best=null,bs=null;cands.forEach((d,i)=>{if(taken.has(d))return;const s=[ld[d]||0,Math.abs(i-target)];if(!bs||s[0]<bs[0]||(s[0]===bs[0]&&s[1]<bs[1])){best=d;bs=s;}});return best;}
function pickDates(cands,ld,k){const n=cands.length,out=new Set();k=Math.min(k,n);for(let j=0;j<k;j++){const target=k===1?0:Math.round(j*(n-1)/(k-1));const taken=new Set(out);cands.forEach((d,i)=>{if(Math.abs(i-target)>2)taken.add(d);});let d=pickBest(cands,ld,taken,target);if(!d)d=pickBest(cands,ld,out,target);out.add(d);ld[d]=(ld[d]||0)+1;}return Array.from(out).sort();}
async function load(){const r=await tessera.call('data.read',{});tasks=r.data.tasks||[];rules=r.data.rules||[];cards=r.data.cards||[];revs=r.revisions||{};render();}
